-- Phase 8: Account page, feedback, legal content, first-login welcome

-- 8.4: has_seen_welcome on users table
alter table users
  add column if not exists has_seen_welcome boolean not null default false;

-- 8.1: extended profile fields on users
alter table users
  add column if not exists legal_name    text,
  add column if not exists nickname      text,
  add column if not exists phone         text,
  add column if not exists address       text;

-- 8.2: feedback table
create table if not exists feedback (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references tenants(id) on delete cascade,
  user_id     uuid not null references auth.users(id) on delete cascade,
  subject     text not null,
  message     text not null,
  created_at  timestamptz not null default now()
);

create index if not exists feedback_tenant_id_idx on feedback(tenant_id);

alter table feedback enable row level security;

create policy "tenant_feedback_select" on feedback
  for select using ((tenant_id::text) = (auth.jwt() ->> 'tenant_id'));

create policy "tenant_feedback_insert" on feedback
  for insert with check ((tenant_id::text) = (auth.jwt() ->> 'tenant_id'));

-- 8.3: legal_pages table (content managed here, not hardcoded)
create table if not exists legal_pages (
  slug        text primary key,   -- 'privacy-policy' | 'terms-of-service'
  title       text not null,
  content     text not null,      -- markdown
  updated_at  timestamptz not null default now()
);

